ALTER TABLE book_requests ADD COLUMN external_code varchar(64);
UPDATE book_requests SET external_code='REQ-' || request_number;
ALTER TABLE book_requests ALTER COLUMN external_code SET NOT NULL;
ALTER TABLE book_requests ALTER COLUMN external_code SET DEFAULT ('REQ-' || gen_random_uuid()::text);
ALTER TABLE book_requests ADD CONSTRAINT uq_request_external_code UNIQUE(external_code);
ALTER TABLE book_requests ADD CONSTRAINT ck_request_copies CHECK(requested_copies BETWEEN 1 AND 1000);
CREATE TABLE tags (name varchar(60) PRIMARY KEY);
CREATE TABLE book_request_tags(request_id uuid NOT NULL REFERENCES book_requests(id) ON DELETE CASCADE,tag_name varchar(60) NOT NULL REFERENCES tags(name),PRIMARY KEY(request_id,tag_name));
CREATE INDEX idx_request_tags_name ON book_request_tags(tag_name);
CREATE INDEX idx_requests_archive_status ON book_requests(archived,status);
CREATE INDEX idx_requests_urgent_copies ON book_requests(urgent,requested_copies);
CREATE INDEX idx_requests_title_lower ON book_requests(lower(book_title));
CREATE INDEX idx_requests_author_lower ON book_requests(lower(book_author));
CREATE TABLE request_notes(id uuid PRIMARY KEY,request_id uuid NOT NULL REFERENCES book_requests(id) ON DELETE CASCADE,author_id uuid REFERENCES app_users(id) ON DELETE SET NULL,author_login varchar(128) NOT NULL,text varchar(4000) NOT NULL,pinned boolean NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,version bigint NOT NULL DEFAULT 0);
CREATE INDEX idx_notes_request ON request_notes(request_id,pinned,created_at);
CREATE TABLE audit_events(id uuid PRIMARY KEY,actor_login varchar(128) NOT NULL,action varchar(40) NOT NULL,entity_type varchar(40) NOT NULL,entity_id uuid,occurred_at timestamptz NOT NULL,description varchar(500) NOT NULL,correlation_id varchar(64) NOT NULL);
CREATE INDEX idx_audit_time ON audit_events(occurred_at);
CREATE INDEX idx_audit_entity ON audit_events(entity_id);
CREATE TABLE import_batches(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES app_users(id),content text NOT NULL,mode varchar(20) NOT NULL,versions text NOT NULL,expires_at timestamptz NOT NULL,valid_rows integer NOT NULL,invalid_rows integer NOT NULL,applied boolean NOT NULL DEFAULT false,created_count integer NOT NULL DEFAULT 0,updated_count integer NOT NULL DEFAULT 0);
